3. Implement the processSubitems function with incremental updates:
```typescript
async function processSubitems(order) {
  const { id, mondayItemId, data } = order;
  const subitems = data.lineItems || [];

  // Update processing status
  await supabase
    .from('formResponses')
    .update({ processingStatus: 'processing' })
    .eq('id', id);

  // Process subitems with bounded concurrency
  const results = [];
  const concurrencyLimit = 3; // Process 3 at a time

  for (let i = 0; i < subitems.length; i += concurrencyLimit) {
    const batch = subitems.slice(i, i + concurrencyLimit);
    const batchPromises = batch.map(async (item, index) => {
      try {
        const subitemId = await createMondaySubitem(mondayItemId, item);

        // Incrementally update the database with each successful subitem
        const updatedData = { ...data };
        updatedData.lineItems[i + index].mondaySubitemId = subitemId;

        await supabase
          .from('formResponses')
          .update({ data: updatedData })
          .eq('id', id);

        return { success: true, item, subitemId };
      } catch (error) {
        return { success: false, item, error: error.message };
      }
    });

    const batchResults = await Promise.all(batchPromises);
    results.push(...batchResults);
  }

  // Update final processing status
  const allSuccessful = results.every(r => r.success);
  await supabase
    .from('formResponses')
    .update({ 
      processingStatus: allSuccessful ? 'completed' : 'failed',
      processingMeta: { results }
    })
    .eq('id', id);
}
```

1. Create a utility function for making resilient API calls to Monday:
```typescript
// utils/mondayApi.ts
export async function resilientMondayApiCall(apiCallFn, maxRetries = 5) {
  let retryCount = 0;

  while (retryCount < maxRetries) {
    try {
      return await apiCallFn();
    } catch (error) {
      // Check if it's a rate limit error
      if (error.status === 429 || error.message?.includes('rate limit')) {
        const backoffTime = Math.pow(2, retryCount) * 1000; // Exponential backoff
        console.log(`Rate limited. Retrying in ${backoffTime}ms (attempt ${retryCount + 1}/${maxRetries})`);

        await new Promise(resolve => setTimeout(resolve, backoffTime));
        retryCount++;
      } else if (isTransientError(error)) {
        // Handle other transient errors (network issues, etc.)
        const backoffTime = Math.pow(1.5, retryCount) * 1000;
        console.log(`Transient error: ${error.message}. Retrying in ${backoffTime}ms`);

        await new Promise(resolve => setTimeout(resolve, backoffTime));
        retryCount++;
      } else {
        // Non-retryable error
        throw error;
      }
    }
  }

  throw new Error(`Failed after ${maxRetries} retries`);
}

function isTransientError(error) {
  // Identify network errors, timeouts, and other transient issues
  return (
    error.code === 'ECONNRESET' ||
    error.code === 'ETIMEDOUT' ||
    error.message?.includes('timeout') ||
    error.message?.includes('network') ||
    error.status >= 500
  );
}
```

