        }
      `;
    });

    const query = `mutation {
      ${batchQueries.join('\n')}
    }`;

    const batchResults = await resilientMondayApiCall(async () => {
      const response = await fetch('https://api.monday.com/v2', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': process.env.MONDAY_API_TOKEN
        },
