3. Implement concurrency control for API calls:
```typescript
class MondayApiRateLimiter {
  constructor(maxConcurrent = 3, intervalMs = 1000) {
    this.queue = [];
    this.running = 0;
    this.maxConcurrent = maxConcurrent;
    this.intervalMs = intervalMs;
    this.lastCallTime = 0;
  }

  async execute(fn) {
    return new Promise((resolve, reject) => {
      this.queue.push({ fn, resolve, reject });
      this.processQueue();
    });
  }

  async processQueue() {
    if (this.running >= this.maxConcurrent || this.queue.length === 0) {
      return;
    }

    const now = Date.now();
    const timeToWait = Math.max(0, this.intervalMs - (now - this.lastCallTime));

    setTimeout(() => {
      if (this.queue.length === 0) return;

      const { fn, resolve, reject } = this.queue.shift();
      this.running++;
      this.lastCallTime = Date.now();

      fn().then(
        result => {
          this.running--;
          resolve(result);
          this.processQueue();
        },
        error => {
          this.running--;
          reject(error);
          this.processQueue();
        }
      );
    }, timeToWait);
  }
}

// Usage:
const mondayRateLimiter = new MondayApiRateLimiter(3, 1000); // 3 concurrent, 1 second interval

async function rateLimitedMondayCall(fn) {
  return mondayRateLimiter.execute(fn);
}
