// utils/processingStatus.ts
import { supabase } from '../lib/supabaseClient';
import { ProcessingStatus, ProcessingMeta } from '../types/database';

export async function updateProcessingStatus(
  id: number,
  status: ProcessingStatus,
  metaUpdates?: Partial<ProcessingMeta>
) {
  // Get current meta if we're updating it
  let currentMeta: ProcessingMeta = {};
  if (metaUpdates) {
    const { data } = await supabase
      .from('formResponses')
      .select('processingMeta')
      .eq('id', id)
      .single();

    currentMeta = data?.processingMeta || {};
  }

  // Update status and meta
  return supabase
    .from('formResponses')
    .update({
      processingStatus: status,
      ...(metaUpdates ? { processingMeta: { ...currentMeta, ...metaUpdates } } : {}),
      updatedAt: new Date().toISOString()
    })
    .eq('id', id);
}

export async function recordItemResult(
  formResponseId: number,
  itemIndex: number,
  result: {
    status: 'pending' | 'success' | 'failed';
    mondaySubitemId?: string;
    error?: string;
  }
) {
  // Get current meta
  const { data } = await supabase
    .from('formResponses')
    .select('processingMeta')
    .eq('id', formResponseId)
    .single();

  const meta = data?.processingMeta || {};
  const itemResults = meta.itemResults || [];

  // Update or add the item result
  itemResults[itemIndex] = {
    id: itemIndex,
    ...result
  };

  // Update the meta
  return supabase
    .from('formResponses')
    .update({
      processingMeta: { ...meta, itemResults },
