async function updateFormResponse(id, updateData) {
  // Fetch the existing form response
  const { data: formResponse } = await supabase
    .from('formResponses')
    .select('*')
    .eq('id', id)
    .single();

  if (!formResponse) {
    throw new Error('Form response not found');
  }

  // Get all required Monday data in a single query
  const mondayItemId = formResponse.mondayItemId;
  const lineItems = formResponse.data.lineItems || [];

  // Extract subitem IDs
  const subitemIds = lineItems.map(item => item.mondaySubitemId).filter(Boolean);

  // Batch update the subitems
  await updateMondaySubitems(subitemIds, updateData);

  // Update local database
  return supabase
    .from('formResponses')
    .update({
      data: {
        ...formResponse.data,
        checkinData: updateData,
        checkinTimestamp: new Date().toISOString()
      },
      updatedAt: new Date().toISOString()
    })
    .eq('id', id);
}

async function updateMondaySubitems(subitemIds, updateData) {
  if (!subitemIds.length) return;

  // Create a batch mutation for all subitems
  const batchMutations = subitemIds.map((id, index) => {
    // Convert updateData to Monday column values format
    const columnValues = convertToMondayColumnValues(updateData);

    return `
      update_${index}: change_multiple_column_values(
        item_id: ${id},
        board_id: ${process.env.MONDAY_BOARD_ID},
        column_values: ${JSON.stringify(columnValues)}
      ) {
        id
      }
    `;
  });

  const query = `mutation {
    ${batchMutations.join('\n')}
  }`;

  // Execute with retry logic
  return resilientMondayApiCall(async () => {
    const response = await fetch('https://api.monday.com/v2', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': process.env.MONDAY_API_TOKEN
      },
      body: JSON.stringify({ query })
    });

    const data = await response.json();
    if (data.errors) throw new Error(data.errors[0].message);

    return data.data;
  });
}

function convertToMondayColumnValues(updateData) {
  // Map the updateData fields to Monday column IDs
  const columnMapping = {
    returnDate: 'date4',
    returnQuantity: 'numbers8',
    condition: 'status8',
    notes: 'text9'
  };

  const columnValues = {};

  Object.entries(updateData).forEach(([key, value]) => {
    const columnId = columnMapping[key];
    if (columnId && value !== undefined) {
      // Format the value based on column type
      if (key === 'returnDate') {
        columnValues[columnId] = { date: value };
      } else if (key === 'condition') {
        columnValues[columnId] = { label: value };
      } else {
        columnValues[columnId] = value.toString();
      }
    }
  });

  return columnValues;
}
```

