export function logApiCall(context, apiName, startTime, result) {
  const duration = Date.now() - startTime;

  if (result.success) {
    logger.info({
      context,
      api: apiName,
      duration,
      success: true
    }, `API call to ${apiName} succeeded in ${duration}ms`);
  } else {
    logger.error({
      context,
      api: apiName,
      duration,
      success: false,
      error: result.error
    }, `API call to ${apiName} failed after ${duration}ms: ${result.error}`);
  }
}

export function logProcessingStep(logger, step, startTime, result) {
  const duration = Date.now() - startTime;

  if (result.success) {
    logger.info({
      step,
      duration,
      success: true,
      ...result.data
    }, `Step ${step} completed in ${duration}ms`);
  } else {
    logger.error({
      step,
      duration,
      success: false,
      error: result.error
    }, `Step ${step} failed after ${duration}ms: ${result.error}`);
  }
}
