async function processOrder(order) {
  const orderLogger = createOrderLogger(order.id);
  orderLogger.info({ order: { id: order.id } }, 'Starting order processing');

  const startTime = Date.now();

  try {
    // Create Monday item
    const itemStartTime = Date.now();
    let mondayItemId;

    try {
      mondayItemId = await createMondayItem(order);
      logProcessingStep(orderLogger, 'create-monday-item', itemStartTime, {
        success: true,
        data: { mondayItemId }
      });
    } catch (error) {
      logProcessingStep(orderLogger, 'create-monday-item', itemStartTime, {
        success: false,
        error: error.message
      });
      throw error;
    }

    // Update database with mondayItemId
    const dbStartTime = Date.now();
    try {
      await updateProcessingStatus(order.id, 'processing', {
        startedAt: new Date().toISOString(),
        mondayItemId
      });

      logProcessingStep(orderLogger, 'update-db-with-item-id', dbStartTime, {
        success: true
      });
    } catch (error) {
      logProcessingStep(orderLogger, 'update-db-with-item-id', dbStartTime, {
        success: false,
        error: error.message
      });
      throw error;
    }

    // Process subitems
    const subitemsStartTime = Date.now();
    try {
      await processSubitems(order, mondayItemId, orderLogger);
      logProcessingStep(orderLogger, 'process-subitems', subitemsStartTime, {
        success: true
      });
    } catch (error) {
      logProcessingStep(orderLogger, 'process-subitems', subitemsStartTime, {
        success: false,
        error: error.message
      });
      throw error;
    }

    // Complete processing
    await updateProcessingStatus(order.id, 'completed', {
      completedAt: new Date().toISOString(),
      duration: Date.now() - startTime
    });

    orderLogger.info({
      duration: Date.now() - startTime
    }, `Order processing completed successfully in ${Date.now() - startTime}ms`);

    return { success: true, orderId: order.id, mondayItemId };
  } catch (error) {
    // Log failure and update status
    orderLogger.error({
      error: error.message,
      stack: error.stack,
      duration: Date.now() - startTime
    }, `Order processing failed after ${Date.now() - startTime}ms: ${error.message}`);

    await updateProcessingStatus(order.id, 'failed', {
      completedAt: new Date().toISOString(),
      duration: Date.now() - startTime,
      errors: [
        {
          message: error.message,
          timestamp: new Date().toISOString(),
          code: error.code
        }
      ]
    });

    return { success: false, orderId: order.id, error: error.message };
  }
}
