// utils/metrics.ts
class MetricsCollector {
  private metrics: Record<string, any[]> = {};

  recordDuration(name: string, durationMs: number, tags: Record<string, string> = {}) {
    if (!this.metrics[name]) {
      this.metrics[name] = [];
    }

    this.metrics[name].push({
      value: durationMs,
      timestamp: Date.now(),
      tags
    });
  }

  recordCount(name: string, count: number = 1, tags: Record<string, string> = {}) {
    if (!this.metrics[name]) {
      this.metrics[name] = [];
    }

    this.metrics[name].push({
      value: count,
      timestamp: Date.now(),
      tags
    });
  }

  getMetrics() {
    return this.metrics;
  }

  clear() {
    this.metrics = {};
  }
}

export const metrics = new MetricsCollector();

// Helper to time a function execution
export async function timed<T>(name: string, fn: () => Promise<T>, tags: Record<string, string> = {}): Promise<T> {
  const start = Date.now();
  try {
    const result = await fn();
    const duration = Date.now() - start;
    metrics.recordDuration(name, duration, tags);
    return result;
  } catch (error) {
    const duration = Date.now() - start;
    metrics.recordDuration(name, duration, { ...tags, error: 'true' });
    throw error;
  }
}
