// loadtest/checkout.js
import http from 'k6/http';
import { sleep, check } from 'k6';

export const options = {
  stages: [
    { duration: '30s', target: 10 }, // Ramp up to 10 users
    { duration: '1m', target: 10 },  // Stay at 10 users for 1 minute
    { duration: '30s', target: 0 },  // Ramp down to 0 users
  ],
  thresholds: {
    http_req_duration: ['p(95)<2000'], // 95% of requests should complete within 2s
    http_req_failed: ['rate<0.01'],     // Less than 1% of requests should fail
  },
};

export default function() {
  // Create a test order
  const payload = JSON.stringify({
    customerName: 'Load Test User',
    email: `test-${Date.now()}@example.com`,
    lineItems: [
      {
        name: 'Test Item 1',
        quantity: 1
      },
      {
        name: 'Test Item 2',
        quantity: 2
      }
    ]
  });

  const params = {
    headers: {
      'Content-Type': 'application/json',
    },
  };

  // Submit the order
  const createResponse = http.post('https://staging-quest-inventory.vercel.app/api/orders', payload, params);

  check(createResponse, {
    'Order created successfully': (r) => r.status === 200,
    'Response includes mondayItemId': (r) => JSON.parse(r.body).mondayItemId !== undefined,
  });

  if (createResponse.status === 200) {
    const orderId = JSON.parse(createResponse.body).id;

    // Poll for status updates
    let processingComplete = false;
    let attempts = 0;

    while (!processingComplete && attempts < 10) {
      sleep(3);
      attempts++;

      const statusResponse = http.get(`https://staging-quest-inventory.vercel.app/api/orders/${orderId}/status`, params);

      if (statusResponse.status === 200) {
        const status = JSON.parse(statusResponse.body).processingStatus;
        processingComplete = (status === 'completed' || status === 'failed');

        check(statusResponse, {
          'Status check successful': (r) => r.status === 200,
          'Processing completed': (r) => processingComplete,
        });
      }
    }
  }

  sleep(1);
}
